INSERT INTO countries (code, name, slug, locale, currency, flag, tagline, intro, monthly_searches, search_note) VALUES ('us', 'United States', 'us', 'en-US', 'USD', '🇺🇸', 'High-intent Thai massage searches across America’s biggest cities', 'The United States is the largest English-language market for “Thai massage near me” and city-modified keywords. Dedicated landing pages for New York, Los Angeles, Chicago, Miami, San Francisco and Las Vegas capture bookers who are ready to visit a studio today.', 89000, 'Modelled from US “massage near me” (3.35M/mo industry head term) plus city-modified Thai massage queries. USA is the volume leader in English.');
INSERT INTO countries (code, name, slug, locale, currency, flag, tagline, intro, monthly_searches, search_note) VALUES ('uk', 'United Kingdom', 'uk', 'en-GB', 'GBP', '🇬🇧', '2,183 Thai massage therapists and dense London–Manchester demand', 'The UK has a large, fragmented Thai massage market (2,183 listed therapists in 2026). London alone accounts for hundreds of storefronts, with strong secondary demand in Manchester, Birmingham, Edinburgh, Glasgow and Bristol.', 41000, 'Supply signal: 2,183 UK Thai massage therapists (POI data, 2026). London is 13.9% of national listings.');
INSERT INTO countries (code, name, slug, locale, currency, flag, tagline, intro, monthly_searches, search_note) VALUES ('au', 'Australia', 'au', 'en-AU', 'AUD', '🇦🇺', 'Home market expanded beyond Melbourne and Sydney', 'Australia remains the brand’s origin market. Expanding from Melbourne and Sydney into Brisbane, Perth and Adelaide keeps existing rankings while opening new city folders on the same .com authority.', 22000, 'Existing Melbourne/Sydney equity plus national “Thai massage [city]” demand across five capitals.');
INSERT INTO countries (code, name, slug, locale, currency, flag, tagline, intro, monthly_searches, search_note) VALUES ('de', 'Germany', 'de', 'de-DE', 'EUR', '🇩🇪', 'Fourth country: Berlin keywords alone exceed 43,000 monthly searches', 'Germany is the fourth country because public SERP keyword databases show exceptional commercial demand. Berlin variants alone include “thai massage in berlin” (16,400), “thaimassagen berlin” (14,300), “thai massagen berlin” (7,400) and “thaimassage berlin” (5,000).', 74000, 'Documented Berlin monthly searches: 16,400 + 14,300 + 7,400 + 5,000 = 43,100 for core variants (Performance Suite keyword DB). Highest measured city cluster of the four countries.');

INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('us', 'new-york', 'New York', 'NY', 'New York searchers look for Thai massage in Midtown, the East Village, Brooklyn and Queens after long commute days. This page targets “Thai massage New York”, “best Thai massage Manhattan” and neighbourhood modifiers.', 'New_York_City', 18500, 40.7128, -74.006);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('us', 'los-angeles', 'Los Angeles', 'CA', 'Los Angeles combines wellness tourism with neighbourhood studios in Hollywood, Santa Monica, Downtown and the Valley. Landing copy is built for “Thai massage Los Angeles” and “traditional Thai massage LA”.', 'Los_Angeles', 14200, 34.0522, -118.2437);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('us', 'chicago', 'Chicago', 'IL', 'Chicago demand clusters around the Loop, Lincoln Park and River North. Winter months lift indoor wellness searches including Thai massage and foot massage.', 'Chicago', 6100, 41.8781, -87.6298);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('us', 'miami', 'Miami', 'FL', 'Miami Thai massage queries mix residents and hotel guests in Brickell, South Beach and Wynwood. English and Spanish bilingual storefronts are common.', 'Miami', 5400, 25.7617, -80.1918);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('us', 'san-francisco', 'San Francisco', 'CA', 'San Francisco searches concentrate in SoMa, Mission and the Financial District, with strong lunchtime and after-work booking intent.', 'San_Francisco', 4800, 37.7749, -122.4194);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('us', 'las-vegas', 'Las Vegas', 'NV', 'Las Vegas Thai massage keywords include Strip-adjacent spas and neighbourhood studios used by locals between shift work and visitor stays.', 'Las_Vegas', 3900, 36.1699, -115.1398);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('uk', 'london', 'London', 'England', 'London is the UK’s densest Thai massage market. High-intent terms include “Thai massage London”, “Thai massage near me” and borough names such as Shoreditch, Chelsea and Soho.', 'London', 16800, 51.5072, -0.1276);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('uk', 'manchester', 'Manchester', 'England', 'Manchester is the brief’s example city for “Best Thai massage in Manchester”. The Northern Quarter, Deansgate and Spinningfields are typical studio corridors.', 'Manchester', 4200, 53.4808, -2.2426);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('uk', 'birmingham', 'Birmingham', 'England', 'Birmingham Thai massage searches cover the city centre, Jewellery Quarter and suburbs used by commuters from the West Midlands.', 'Birmingham', 2800, 52.4862, -1.8904);
INSERT INTO cities (country_code, slug, name, region, intro, wiki_title, monthly_searches, lat, lng) VALUES ('uk', 'edinburgh', 'Edinburgh', 'Scotland', 'Edinburgh demand is year-round with festival-season spikes. Visitors search “Thai massage Edinburgh Old Town” and nearby New Town addresses.', 'Edinburgh', 1900, 55.9533, -3.1883);
